#!/usr/bin/env bash
# SecLab performance benchmark. Measures what the security controls COST.
#     bash tests/bench.sh          label = the active profile  (hardened / baseline)
#     bash tests/bench.sh noids    label = <profile>-noids  (run after stopping the IDS,
#                                  see P12 in the continuation guide)
#
# All load is generated by "remote", i.e. from the customer's side of the
# perimeter, so every request crosses the edge firewall, NAT, the IDS sensor,
# the web server, the firewall again, core, the application server and the database.
#
# Raw results go to evidence/bench/ as CSV. Nothing is averaged here - the
# statistics are done afterwards by analysis/analyse.py from the raw samples.
set -u
cd "$(dirname "$0")/.."

PROFILE="$(cat state/profile)"
LABEL="$PROFILE${1:+-$1}"
OUT=evidence/bench
mkdir -p "$OUT"
BASE=http://portal.seclab.test
[ "$PROFILE" = hardened ] && BASE=https://portal.seclab.test

N_LATENCY=300      # samples per latency series
N_DOWNLOAD=10      # downloads of the 20 MB file
N_CAPACITY=5       # repetitions of the load test
# curl -w output formats (one CSV line per request)
TIMES='%{http_code},%{time_connect},%{time_appconnect},%{time_starttransfer},%{time_total}'
DL='%{http_code},%{size_download},%{time_total},%{speed_download}'
echo "=== benchmark: label=$LABEL  target=$BASE  $(date) ==="

# ---- 1. cold latency: a NEW connection for every request -------------------
# Each sample includes the TCP handshake and (hardened) the full TLS handshake.
# curl reports its own timings, so docker-exec overhead is not in the numbers.
echo "[1/5] cold-connection latency ($N_LATENCY samples)"
{
  echo "label,series,sample,http_code,t_connect,t_tls,t_first_byte,t_total"
  docker exec remote bash -c "
    for i in \$(seq 1 $N_LATENCY); do
      curl -s -o /dev/null -m 10 -w '$LABEL,cold,'\$i',$TIMES\n' $BASE/api/summary
      sleep 0.05
    done"
} > "$OUT/latency-cold-$LABEL.csv"

# ---- 2. warm latency: ONE connection reused for all requests ---------------
# Passing many URLs to a single curl process makes it keep the connection open,
# so this series shows the steady-state cost per request (no handshakes).
echo "[2/5] warm-connection latency ($N_LATENCY samples)"
{
  echo "label,series,sample,http_code,t_connect,t_tls,t_first_byte,t_total"
  docker exec remote bash -c "
    urls=''; for i in \$(seq 1 $N_LATENCY); do urls=\"\$urls -o /dev/null $BASE/api/summary\"; done
    curl -s -m 120 --rate 20/s -w '$LABEL,warm,%{urlnum},$TIMES\n' \$urls"
} > "$OUT/latency-warm-$LABEL.csv"

# ---- 3. throughput: download a 20 MB file ----------------------------------
echo "[3/5] bulk transfer throughput ($N_DOWNLOAD downloads of 20 MB)"
{
  echo "label,sample,http_code,bytes,seconds,bytes_per_second"
  docker exec remote bash -c "
    for i in \$(seq 1 $N_DOWNLOAD); do
      curl -s -o /dev/null -m 120 -w '$LABEL,'\$i',$DL\n' $BASE/files/testfile.bin
    done"
} > "$OUT/throughput-$LABEL.csv"

# ---- 4. capacity: ApacheBench, 3000 requests, 20 concurrent, static page ----
# Run twice: without keep-alive (every request opens a new connection, so in
# the hardened profile every request pays for a TLS handshake) and with
# keep-alive (-k: connections are reused, as real browsers do).
# The static page is used (not /api/) so that the API rate limit - a control
# with its own test, C09 - does not cap the result.
echo "[4/5] request capacity ($N_CAPACITY runs each of ab -n 3000 -c 20," \
     "without and with keep-alive)"
{
  echo "label,keepalive,run,requests_per_second,mean_ms,p50_ms,p95_ms,p99_ms,failed"
  for mode in no yes; do
    flag=""; [ "$mode" = yes ] && flag="-k"
    for run in $(seq 1 $N_CAPACITY); do
      raw="$OUT/ab-raw-$LABEL-keepalive_$mode-$run.txt"
      docker exec remote ab -q $flag -n 3000 -c 20 "$BASE/" > "$raw" 2>&1
      awk -v label="$LABEL" -v mode="$mode" -v run="$run" '
        /^Requests per second/ {rps=$4}
        /^Time per request/ && !seen {mean=$4; seen=1}
        /^Failed requests/ {failed=$3}
        /^ +50%/ {p50=$2} /^ +95%/ {p95=$2} /^ +99%/ {p99=$2}
        END {printf "%s,%s,%s,%s,%s,%s,%s,%s,%s\n",
                    label, mode, run, rps, mean, p50, p95, p99, failed}' "$raw"
    done
  done
} > "$OUT/capacity-$LABEL.csv"

# ---- 5. resource use under load --------------------------------------------
# Start a 15-second load (static page, as in step 4) in the background, then
# sample CPU and memory of the nodes on the request path five times.
echo "[5/5] CPU and memory under load"
docker exec -d remote ab -q -t 15 -n 1000000 -c 20 "$BASE/"
sleep 3
{
  echo "label,sample,node,cpu_percent,mem_usage"
  for s in 1 2 3 4 5; do
    docker stats --no-stream --format '{{.Name}},{{.CPUPerc}},{{.MemUsage}}' edge core web app db \
      | sed "s/^/$LABEL,$s,/; s/%//; s| / .*||"
    sleep 1
  done
} > "$OUT/resources-$LABEL.csv"
sleep 8

echo "done. Files written:"
ls -1 "$OUT" | grep -- "-$LABEL" | sed 's/^/  /'
